const webhook = $json && typeof $json === 'object' ? $json : {};
let body = webhook.body ?? webhook;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};
const headers = webhook.headers && typeof webhook.headers === 'object' ? webhook.headers : {};
const normalizedHeaders = Object.fromEntries(Object.entries(headers).map(([key, value]) => [key.toLowerCase(), String(value ?? '')]));
const suppliedSecret = normalizedHeaders['x-codex-notify-secret'] || normalizedHeaders['x-codex-notify-secret-token'] || '';
const expectedSecret = String($vars.CODEX_NOTIFY_SECRET ?? '').trim();
const event = String(body.event ?? body.type ?? body.event_name ?? '').trim();
const threadId = String(body.threadId ?? body.thread_id ?? body['thread-id'] ?? '').trim();
const turnId = String(body.turnId ?? body.turn_id ?? body['turn-id'] ?? '').trim();
const cwd = String(body.cwd ?? '').trim();

function rejected(statusCode, error, extra = {}) {
  return [{ json: { accepted: false, statusCode, error, ...extra } }];
}
if (!expectedSecret) return rejected(503, 'notification configuration unavailable');
if (!suppliedSecret || suppliedSecret !== expectedSecret) return rejected(401, 'unauthorized');
if (!String($vars.TELEGRAM_ADMIN_USER_ID ?? '').trim() || !String($vars.KOOK_ADMIN_USER_ID ?? '').trim()) return rejected(503, 'admin recipient configuration unavailable');
if (event !== 'agent-turn-complete') return rejected(400, 'ignored non-completion event', { ignored: true });
if (!threadId || !turnId || !cwd) return rejected(400, 'completion payload missing required identity fields');
if (threadId.length > 256 || turnId.length > 256 || cwd.length > 4096) return rejected(400, 'completion payload field too long');

const projectBase = cwd.replace(/[\\/]+$/u, '').split(/[\\/]/u).filter(Boolean).pop() || 'unknown-project';
const projectName = projectBase.replace(/[^A-Za-z0-9._-]+/gu, '_').replace(/^[-._]+|[-._]+$/gu, '').slice(0, 80) || 'unknown-project';
const message = String(body.lastAssistantMessage ?? body.last_assistant_message ?? body['last-assistant-message'] ?? '').trim().slice(0, 8000);
const timestampValue = String(body.timestamp ?? body.completedAt ?? body.completed_at ?? '').trim();
const parsedTimestamp = Date.parse(timestampValue);
const timestamp = Number.isFinite(parsedTimestamp) ? new Date(parsedTimestamp).toISOString() : new Date().toISOString();
const idempotencyKey = `${threadId}:${turnId}`;

return [{ json: { accepted: true, duplicate: false, statusCode: 200, event, threadId, turnId, cwd, projectName, message, timestamp, idempotencyKey } }];

const input = $('Resolve Idempotency').first()?.json ?? $('Validate Completion').first()?.json ?? $json;
function redact(value) {
  let result = String(value ?? '').replace(/[\\\r\n]+/gu, ' ').trim();
  result = result.replace(/Bearer\s+[A-Za-z0-9._-]{16,}/giu, 'Bearer [REDACTED]');
  result = result.replace(/\bsk-[A-Za-z0-9_-]{16,}\b/gu, '[REDACTED]');
  result = result.replace(/\bgh[pousr]_[A-Za-z0-9_]{16,}\b/gu, '[REDACTED]');
  result = result.replace(/\b(api[_-]?key|access[_-]?token|bot[_-]?token|app[_-]?secret|jwt[_-]?secret|password)\s*[:=]\s*[^\s,;]+/giu, '$1=[REDACTED]');
  return result.slice(0, 8000);
}
const time = new Date(input.timestamp);
const timeLabel = Number.isFinite(time.getTime())
  ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(time)
  : '未知时间';
const displayCwd = String(input.cwd ?? '').replace(/^\/Users\/[^/]+/u, '~').replace(/^\/home\/[^/]+/u, '~');
const message = redact(input.message) || 'Codex agent turn completed.';
const text = `✅ Codex 执行完成\n\n项目：${input.projectName}\n目录：${displayCwd}\n时间：${timeLabel}\n\n结果：\n${message}`;
const telegramTarget = String($vars.TELEGRAM_ADMIN_USER_ID ?? '').trim();
const kookTarget = String($vars.KOOK_ADMIN_USER_ID ?? '').trim();
if (!telegramTarget || !kookTarget) throw new Error('admin recipient configuration unavailable');
const chain = [{ type: 'Plain', text }];
return [{ json: {
  accepted: true,
  event: input.event,
  threadId: input.threadId,
  turnId: input.turnId,
  idempotencyKey: input.idempotencyKey,
  projectName: input.projectName,
  cwd: input.cwd,
  timestamp: input.timestamp,
  message: input.message,
  notificationText: text,
  telegramBody: { target_type: 'person', target_id: telegramTarget, message_chain: chain },
  kookBody: { target_type: 'person', target_id: kookTarget, message_chain: chain },
} }];

const formatted = $('Format Notification').first()?.json ?? {};
const telegramRaw = $('Send Telegram DM').first()?.json ?? {};
const kookRaw = $('Send KOOK DM').first()?.json ?? {};
function delivery(value) {
  const statusCode = Number(value?.statusCode ?? 0);
  const body = value?.body && typeof value.body === 'object' ? value.body : value;
  const error = value?.error || body?.error;
  const sent = !error && ((Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300) || body?.data?.sent === true || body?.sent === true);
  return { status: sent ? 'sent' : 'failed', ...(Number.isInteger(statusCode) && statusCode > 0 ? { statusCode } : {}), ...(!sent ? { reason: 'platform_request_failed' } : {}) };
}
return [{ json: {
  accepted: true,
  duplicate: false,
  event: formatted.event,
  threadId: formatted.threadId,
  turnId: formatted.turnId,
  idempotencyKey: formatted.idempotencyKey,
  projectName: formatted.projectName,
  timestamp: formatted.timestamp,
  telegram: delivery(telegramRaw),
  kook: delivery(kookRaw),
  completedAt: new Date().toISOString(),
} }];

const incoming = $('Validate Completion').first()?.json ?? {};
const row = $input.first()?.json ?? {};
const duplicate = String(row.eventKey ?? '') === String(incoming.idempotencyKey ?? '');
return [{ json: { ...incoming, accepted: !duplicate, duplicate, statusCode: 200 } }];
